original_code:
module edge_detector_mealy (
    input logic clk,
    input logic rst_n,
    input logic din,
    output logic rising_edge
);

typedef enum logic {IDLE, HIGH} state_t;
state_t state, next_state;

// State register
always_ff @(posedge clk or negedge rst_n) begin
    case (rst_n)
        1'b0: state <= IDLE;
        1'b1: state <= next_state;
    endcase
end

// Next state and output logic (Mealy)
always_comb begin
    next_state = state;
    rising_edge = 1'b0;

    case (state)
        IDLE: begin
            case (din)
                1'b1: begin
                    next_state = HIGH;
                    rising_edge = 1'b1;  // Mealy: output depends on input
                end
            endcase
        end

        HIGH: begin
            case (din)
                1'b0: next_state = IDLE;
            endcase
        end
    endcase
end

endmodule

