module crc32_engine (
    input  logic        clk,
    input  logic        rst_n,
    input  logic        data_valid,
    input  logic [31:0] data_in,
    input  logic        crc_init,
    output logic [31:0] crc_out,
    output logic        crc_valid
);

    // Polynomial: 0x04C11DB7 (Ethernet/PCIe)
    localparam CRC_POLY = 32'h04C11DB7;

    // Block 1: CRC Register (Case-only Sequential)
    logic [31:0] crc_reg;
    logic [31:0] crc_next;

    always_ff @(posedge clk or negedge rst_n) begin
        case (rst_n)
            1'b0: crc_reg <= 32'hFFFFFFFF;
            1'b1: begin
                case ({crc_init, data_valid})
                    2'b10, 2'b11: crc_reg <= 32'hFFFFFFFF;  // Init takes priority
                    2'b01:        crc_reg <= crc_next;
                    default:      crc_reg <= crc_reg;
                endcase
            end
        endcase
    end

    // Block 2: Parallel CRC Computation (Combinational)
    always_comb begin
        logic [31:0] data_xor;
        data_xor = data_in ^ crc_reg;

        // Parallel CRC calculation using case for each bit
        // Bit 0
        case (1'b1)
            1'b1: crc_next[0] = data_xor[31] ^ data_xor[29] ^ data_xor[28] ^ data_xor[26] ^
                                 data_xor[25] ^ data_xor[22] ^ data_xor[21] ^ data_xor[20] ^
                                 data_xor[19] ^ data_xor[18] ^ data_xor[17] ^ data_xor[16] ^
                                 data_xor[14] ^ data_xor[13] ^ data_xor[12] ^ data_xor[11] ^
                                 data_xor[9]  ^ data_xor[8]  ^ data_xor[7]  ^ data_xor[5]  ^
                                 data_xor[4]  ^ data_xor[3]  ^ data_xor[0];
        endcase

        // Bit 1
        case (1'b1)
            1'b1: crc_next[1] = data_xor[30] ^ data_xor[28] ^ data_xor[27] ^ data_xor[25] ^
                                 data_xor[24] ^ data_xor[21] ^ data_xor[20] ^ data_xor[19] ^
                                 data_xor[18] ^ data_xor[17] ^ data_xor[16] ^ data_xor[15] ^
                                 data_xor[13] ^ data_xor[12] ^ data_xor[11] ^ data_xor[10] ^
                                 data_xor[8]  ^ data_xor[7]  ^ data_xor[6]  ^ data_xor[4]  ^
                                 data_xor[3]  ^ data_xor[2]  ^ data_xor[1];
        endcase

        // Bit 31
        case (1'b1)
            1'b1: crc_next[31] = data_xor[28] ^ data_xor[27] ^ data_xor[26] ^ data_xor[25] ^
                                 data_xor[24] ^ data_xor[23] ^ data_xor[22] ^ data_xor[21] ^
                                 data_xor[20] ^ data_xor[19] ^ data_xor[18] ^ data_xor[17] ^
                                 data_xor[16] ^ data_xor[15] ^ data_xor[14] ^ data_xor[13] ^
                                 data_xor[12] ^ data_xor[11] ^ data_xor[10] ^ data_xor[9]  ^
                                 data_xor[8]  ^ data_xor[7]  ^ data_xor[6]  ^ data_xor[5]  ^
                                 data_xor[4]  ^ data_xor[3]  ^ data_xor[2]  ^ data_xor[1];
        endcase
    end

    // Block 3: Output Control (Case-only Combinational)
    always_comb begin
        case (data_valid)
            1'b1: begin
                crc_out = ~crc_reg;
                crc_valid = 1'b1;
            end
            default: begin
                crc_out = 32'b0;
                crc_valid = 1'b0;
            end
        endcase
    end

    // Block 4: Error Detection (Case-only Combinational)
    logic [31:0] expected_crc;
    logic crc_error;

    always_comb begin
        expected_crc = 32'hDEBB20E3;
        case (crc_out != expected_crc && crc_valid)
            1'b1: crc_error = 1'b1;
            default: crc_error = 1'b0;
        endcase
    end

endmodule

