module ethernet_packet_parser (
    input  logic        clk,
    input  logic        rst_n,

    // Input data stream
    input  logic        data_valid,
    input  logic [63:0] data_in,      // 64-bit wide data (8 bytes per cycle)
    input  logic        data_start,    // SOP (Start of Packet)
    input  logic        data_end,      // EOP (End of Packet)

    // Output parsed fields
    output logic [47:0] dest_mac,
    output logic [47:0] src_mac,
    output logic [15:0] ethertype,
    output logic [31:0] ipv4_src,
    output logic [31:0] ipv4_dst,
    output logic [15:0] tcp_src_port,
    output logic [15:0] tcp_dst_port,
    output logic [7:0]  ip_protocol,
    output logic        packet_valid,

    // Control outputs
    output logic        ipv4_detected,
    output logic        tcp_detected,
    output logic        udp_detected,
    output logic        vlan_detected,
    output logic        parsing_error
);

    // Block 1: Packet State Machine (Sequential)
    typedef enum logic [2:0] {
        WAIT_SOP   = 3'b000,
        MAC_DEST   = 3'b001,
        MAC_SRC    = 3'b010,
        VLAN_TAG   = 3'b011,
        ETHERTYPE  = 3'b100,
        IP_HEADER  = 3'b101,
        L4_HEADER  = 3'b110,
        PAYLOAD    = 3'b111
    } parse_state_t;

    parse_state_t current_state, next_state;
    logic [4:0] byte_offset;           // Byte position within current 64-bit word (0-7, but 5 bits to avoid overflow)
    logic [5:0] header_byte_count;     // Count of bytes processed in current header (up to 40 bytes for IP header)
    logic [47:0] temp_dest_mac;
    logic [47:0] temp_src_mac;
    logic [15:0] temp_ethertype;
    logic [31:0] temp_ipv4_src;
    logic [31:0] temp_ipv4_dst;
    logic [7:0]  temp_ip_protocol;
    logic [15:0] temp_tcp_src;
    logic [15:0] temp_tcp_dst;
    logic        has_vlan;

    always_ff @(posedge clk or negedge rst_n) begin
        case (rst_n)
            1'b0: current_state <= WAIT_SOP;
            1'b1: current_state <= next_state;
        endcase
    end

    // Block 2: Byte Position and Counters (Sequential)
    always_ff @(posedge clk or negedge rst_n) begin
        case (rst_n)
            1'b0: begin
                byte_offset <= 5'b0;
                header_byte_count <= 6'b0;
            end
            1'b1: begin
                case (current_state)
                    WAIT_SOP: begin
                        case (data_start)
                            1'b1: begin
                                byte_offset <= 5'b0;
                                header_byte_count <= 6'b0;
                            end
                            default: begin
                                byte_offset <= byte_offset;
                                header_byte_count <= header_byte_count;
                            end
                        endcase
                    end

                    MAC_DEST, MAC_SRC, VLAN_TAG, ETHERTYPE, IP_HEADER, L4_HEADER: begin
                        case (data_valid)
                            1'b1: begin
                                byte_offset <= byte_offset + 5'd8;
                                header_byte_count <= header_byte_count + 6'd8;
                            end
                            default: begin
                                byte_offset <= byte_offset;
                                header_byte_count <= header_byte_count;
                            end
                        endcase
                    end

                    default: begin
                        byte_offset <= byte_offset;
                        header_byte_count <= header_byte_count;
                    end
                endcase
            end
        endcase
    end

    // Block 3: State Transition Logic (Case-only Combinational)
    always_comb begin
        next_state = current_state;

        case (current_state)
            WAIT_SOP: begin
                case (data_start)
                    1'b1: next_state = MAC_DEST;
                    default: next_state = WAIT_SOP;
                endcase
            end

            MAC_DEST: begin
                case ({data_valid, (header_byte_count >= 6'd6)})
                    2'b11: next_state = MAC_SRC;
                    default: next_state = MAC_DEST;
                endcase
            end

            MAC_SRC: begin
                case ({data_valid, (header_byte_count >= 6'd12)})
                    2'b11: next_state = ETHERTYPE;
                    default: next_state = MAC_SRC;
                endcase
            end

            ETHERTYPE: begin
                case (data_valid)
                    1'b1: begin
                        case (temp_ethertype)
                            16'h8100: next_state = VLAN_TAG;  // VLAN tag detected
                            default: next_state = IP_HEADER;
                        endcase
                    end
                    default: next_state = ETHERTYPE;
                endcase
            end

            VLAN_TAG: begin
                case ({data_valid, (header_byte_count >= 6'd4)})
                    2'b11: next_state = ETHERTYPE;
                    default: next_state = VLAN_TAG;
                endcase
            end

            IP_HEADER: begin
                case ({data_valid, (header_byte_count >= 6'd20)})
                    2'b11: next_state = L4_HEADER;
                    default: next_state = IP_HEADER;
                endcase
            end

            L4_HEADER: begin
                case (data_valid)
                    1'b1: begin
                        case ({temp_ip_protocol, (header_byte_count >= 6'd4)})
                            {8'd6, 1'b1}: next_state = PAYLOAD;  // TCP
                            {8'd17, 1'b1}: next_state = PAYLOAD;  // UDP
                            default: next_state = L4_HEADER;
                        endcase
                    end
                    default: next_state = L4_HEADER;
                endcase
            end

            PAYLOAD: begin
                case (data_end)
                    1'b1: next_state = WAIT_SOP;
                    default: next_state = PAYLOAD;
                endcase
            end

            default: begin
                case (data_end)
                    1'b1: next_state = WAIT_SOP;
                    default: next_state = current_state;
                endcase
            end
        endcase
    end

    // Block 4: MAC Address Extraction (Combinational with Byte Alignment)
    always_comb begin
        temp_dest_mac = dest_mac;
        temp_src_mac = src_mac;

        case (current_state)
            MAC_DEST: begin
                case (byte_offset[2:0])  // Extract based on byte alignment (lower 3 bits only)
                    3'b000: begin
                        temp_dest_mac[47:40] = data_in[63:56];
                        temp_dest_mac[39:32] = data_in[55:48];
                        temp_dest_mac[31:24] = data_in[47:40];
                        temp_dest_mac[23:16] = data_in[39:32];
                        temp_dest_mac[15:8]  = data_in[31:24];
                        temp_dest_mac[7:0]   = data_in[23:16];
                    end
                    3'b001: begin
                        temp_dest_mac[47:40] = data_in[55:48];
                        temp_dest_mac[39:32] = data_in[47:40];
                        temp_dest_mac[31:24] = data_in[39:32];
                        temp_dest_mac[23:16] = data_in[31:24];
                        temp_dest_mac[15:8]  = data_in[23:16];
                        temp_dest_mac[7:0]   = data_in[15:8];
                    end
                    default: temp_dest_mac = temp_dest_mac;
                endcase
            end

            MAC_SRC: begin
                case (byte_offset[2:0])
                    3'b000: begin
                        temp_src_mac[47:40] = data_in[63:56];
                        temp_src_mac[39:32] = data_in[55:48];
                        temp_src_mac[31:24] = data_in[47:40];
                        temp_src_mac[23:16] = data_in[39:32];
