module pcie_tlp_decoder_asserts  (input logic clk,
input logic rst_n,
input logic tlp_valid,
input logic [63:0] tlp_data, input logic tlp_start, input logic tlp_end, input logic [2:0] tlp_dw_count,
input logic [7:0] tlp_fmt_type, input logic [9:0] tlp_length, input logic [15:0] tlp_requester_id, input logic [15:0] tlp_completer_id, input logic [7:0] tlp_tag, input logic [31:0] tlp_address, input logic [31:0] tlp_data_payload, input logic [3:0] tlp_first_be, input logic [3:0] tlp_last_be,
input logic tlp_mem_read,
input logic tlp_mem_write,
input logic tlp_cfg_read,
input logic tlp_cfg_write,
input logic tlp_completion,
input logic tlp_completion_data,
input logic tlp_parity_error,
input logic tlp_format_error,
input logic tlp_decode_done);

    typedef enum logic [2:0] {
        IDLE          = 3'b000,
        HEADER_DW0    = 3'b001,
        HEADER_DW1    = 3'b010,
        HEADER_DW2    = 3'b011,
        HEADER_DW3    = 3'b100,
        DATA_PAYLOAD  = 3'b101,
        DECODE_DONE   = 3'b110,
        ERROR         = 3'b111
